fun searchLibraryArticles(query: String, lang: String, sections: List<LibrarySection>): String {
    val queryWords = query.lowercase().split(Regex("\\s+"))
        .map { it.replace(Regex("[^a-zA-Z0-9\\u0600-\\u06FF\\u00C0-\\u017F]"), "") }
        .filter { it.length > 2 }

    if (queryWords.isEmpty()) {
        return getFallbackMessage(lang)
    }

    var bestTopic: LibraryTopic? = null
    var bestTitle: String = ""
    var bestScore = 0
    var bestBody: String = ""

    for (section in sections) {
        for (topic in section.topics) {
            val localizedTitle = resolveArticleTitle(topic.title, lang)
            val localizedBody = resolveArticleBody(topic.title, lang, topic.summary)

            var score = 0
            val titleLower = localizedTitle.lowercase()
            val bodyLower = localizedBody.lowercase()

            for (word in queryWords) {
                if (titleLower.contains(word)) {
                    score += 15
                }
                var index = bodyLower.indexOf(word)
                while (index != -1) {
                    score += 3
                    index = bodyLower.indexOf(word, index + word.length)
                }
            }

            if (score > bestScore) {
                bestScore = score
                bestTopic = topic
                bestTitle = localizedTitle
                bestBody = localizedBody
            }
        }
    }

    // Try English fallback if no match found and selected language is not English
    if (bestScore == 0 && lang != "EN") {
        for (section in sections) {
            for (topic in section.topics) {
                val englishTitle = resolveArticleTitle(topic.title, "EN")
                val englishBody = resolveArticleBody(topic.title, "EN", topic.summary)

                var score = 0
                val titleLower = englishTitle.lowercase()
                val bodyLower = englishBody.lowercase()

                for (word in queryWords) {
                    if (titleLower.contains(word)) {
                        score += 15
                    }
                    var index = bodyLower.indexOf(word)
                    while (index != -1) {
                        score += 3
                        index = bodyLower.indexOf(word, index + word.length)
                    }
                }

                if (score > bestScore) {
                    bestScore = score
                    bestTopic = topic
                    bestTitle = resolveArticleTitle(topic.title, lang)
                    bestBody = resolveArticleBody(topic.title, lang, topic.summary)
                }
            }
        }
    }

    if (bestScore > 0 && bestTopic != null) {
        val paragraphs = bestBody.split(Regex("\\n\\s*\\n+"))
            .map { it.trim() }
            .filter { it.isNotEmpty() }

        var bestPara1 = ""
        var bestPara2 = ""
        var pScore1 = -1
        var pScore2 = -1

        for (para in paragraphs) {
            var pScore = 0
            val paraLower = para.lowercase()
            for (word in queryWords) {
                if (paraLower.contains(word)) {
                    pScore += 10
                }
            }
            if (pScore > pScore1) {
                pScore2 = pScore1
                bestPara2 = bestPara1

                pScore1 = pScore
                bestPara1 = para
            } else if (pScore > pScore2) {
                pScore2 = pScore
                bestPara2 = para
            }
        }

        val resultBody = if (bestPara1.isNotEmpty()) {
            if (bestPara2.isNotEmpty() && pScore2 > 0) {
                "$bestPara1\n\n$bestPara2"
            } else {
                bestPara1
            }
        } else {
            paragraphs.firstOrNull() ?: bestBody
        }

        return when (lang) {
            "AR" -> "بناءً على مقال المكتبة **$bestTitle**، إليك ما وجدته:\n\n$resultBody"
            "FR" -> "D'après l'article de la bibliothèque **$bestTitle**, voici ce que j'ai trouvé :\n\n$resultBody"
            "ES" -> "Según el artículo de la biblioteca **$bestTitle**, esto es lo que encontré:\n\n$resultBody"
            "IT" -> "In base all'articolo della biblioteca **$bestTitle**, ecco cosa ho trovato:\n\n$resultBody"
            "DE" -> "Basierend auf dem Bibliotheksartikel **$bestTitle** habe ich Folgendes gefunden:\n\n$resultBody"
            "NL" -> "Op basis van het bibliotheekartikel **$bestTitle** is dit wat ik heb gevonden:\n\n$resultBody"
            else -> "Based on the Library article **$bestTitle**, here is what I found:\n\n$resultBody"
        }
    }

    return getFallbackMessage(lang)
}

@Composable
fun LibraryScreen(onBack: () -> Unit = {}) {
    var expandedSectionIndex by remember { mutableStateOf<Int?>(null) }
    var selectedTopic by remember { mutableStateOf<LibraryTopic?>(null) }

    var showLanguageSelector by remember { mutableStateOf(false) }
    var showUrtiChat by remember { mutableStateOf(false) }
    var selectedChatLang by remember { mutableStateOf("EN") }
    val urtiChatMessages = remember { mutableStateListOf<ChatMessage>() }

    BackHandler(enabled = selectedTopic == null && !showUrtiChat && !showLanguageSelector) {
        onBack()
    }
    var selectedLibraryLang by remember(selectedTopic) { mutableStateOf("EN") }

    val sections = remember { getLibraryData() }

    Box(
        modifier = Modifier
            .fillMaxSize()
            .background(AmoledBlack)
    ) {
        Column(
            modifier = Modifier
                .fillMaxSize()
                .statusBarsPadding()
                .padding(horizontal = 16.dp)
        ) {
            // Header Bar
            Box(
                modifier = Modifier
                    .fillMaxWidth()
                    .padding(top = 16.dp, bottom = 12.dp)
            ) {
                // Back Button
                IconButton(
                    onClick = onBack,
                    modifier = Modifier
                        .align(Alignment.CenterStart)
                        .background(DarkCard, shape = CircleShape)
                        .size(40.dp)
                ) {
                    Text(
                        text = "←",
                        color = LightGray,
                        fontSize = 20.sp,
                        fontWeight = FontWeight.Bold
                    )
                }

                // Centered Title
                Text(
                    text = "📚 Library",
                    color = SoftPurple,
                    fontSize = 20.sp,
                    fontWeight = FontWeight.Bold,
                    modifier = Modifier.align(Alignment.Center)
                )
            }

            // Scrollable Content
            Column(
                modifier = Modifier
                    .weight(1f)
                    .verticalScroll(rememberScrollState())
                    .padding(bottom = 24.dp)
            ) {
                // Welcome / Intro Layout (Not in a box)
                Column(
                    modifier = Modifier
                        .fillMaxWidth()
                        .padding(start = 16.dp, end = 16.dp, bottom = 8.dp),
                    horizontalAlignment = Alignment.CenterHorizontally
                ) {
                    Text(
                        text = "Learn about urticaria subtypes, mast-cell biological loops, medications, lifestyle triggers, and guidelines. Tap any section to view topics, and tap a topic to read its summary.",
                        color = Color(0xFF737373),
                        fontSize = 12.sp,
                        textAlign = TextAlign.Center,
                        lineHeight = 18.sp
                    )
                }

                // Ask Urti Round Button
                Column(
                    modifier = Modifier
                        .fillMaxWidth()
                        .padding(vertical = 12.dp),
                    horizontalAlignment = Alignment.CenterHorizontally
                ) {
                    Image(
                        painter = painterResource(id = R.drawable.urti_avatar),
                        contentDescription = "Ask Urti",
                        modifier = Modifier
                            .size(72.dp)
                            .clip(CircleShape)
                            .background(DarkCard)
                            .border(1.5.dp, SoftPurple.copy(alpha = 0.8f), CircleShape)
                            .clickable { showLanguageSelector = true }
                    )
                    Spacer(modifier = Modifier.height(6.dp))
                    Text(
                        text = "Ask Urti",
                        color = SoftPurple,
                        fontSize = 13.sp,
                        fontWeight = FontWeight.Bold,
                        textAlign = TextAlign.Center
                    )
                }

                // Collapsible Sections List
                sections.forEachIndexed { index, section ->
                    val isExpanded = expandedSectionIndex == index
                    Card(
                        modifier = Modifier
                            .fillMaxWidth()
                            .padding(vertical = 6.dp)
                            .border(1.dp, if (isExpanded) SoftPurple.copy(alpha = 0.5f) else DarkBorder, RoundedCornerShape(12.dp)),
                        colors = CardDefaults.cardColors(containerColor = DarkCard),
                        shape = RoundedCornerShape(12.dp)
                    ) {
                        Column {
                            // Section Header Clickable Row
                            Row(
                                modifier = Modifier
                                    .fillMaxWidth()
                                    .clickable {
                                        expandedSectionIndex = if (isExpanded) null else index
                                    }
                                    .padding(16.dp),
                                horizontalArrangement = Arrangement.SpaceBetween,
                                verticalAlignment = Alignment.CenterVertically
                            ) {
                                Column(modifier = Modifier.weight(1f)) {
                                    Text(
                                        text = section.title,
                                        color = SoftPurple,
                                        fontSize = 14.sp,
                                        fontWeight = FontWeight.Bold
                                    )
                                    Spacer(modifier = Modifier.height(2.dp))
                                    Text(
                                        text = section.description,
                                        color = Color(0xFF1B8097),
                                        fontSize = 11.sp
                                    )
                                }
                                Text(
                                    text = if (isExpanded) "▲" else "▼",
                                    color = SoftPurple,
                                    fontSize = 12.sp,
                                    modifier = Modifier.padding(start = 8.dp)
                                )
                            }

                            // Topics list inside section
                            AnimatedVisibility(visible = isExpanded) {
                                Column(
                                    modifier = Modifier
                                        .fillMaxWidth()
                                        .background(DarkSurface)
                                        .padding(horizontal = 8.dp, vertical = 4.dp)
                                ) {
                                    HorizontalDivider(color = DarkBorder, thickness = 1.dp, modifier = Modifier.padding(bottom = 4.dp))
                                    section.topics.forEach { topic ->
                                        Row(
                                            modifier = Modifier
                                                .fillMaxWidth()
                                                .clickable { selectedTopic = topic }
                                                .padding(vertical = 10.dp, horizontal = 8.dp),
                                            verticalAlignment = Alignment.CenterVertically,
                                            horizontalArrangement = Arrangement.SpaceBetween
                                        ) {
                                            Row(
                                                verticalAlignment = Alignment.CenterVertically,
                                                modifier = Modifier.weight(1f)
                                            ) {
                                                Text(
                                                    text = "📄",
                                                    fontSize = 14.sp,
                                                    modifier = Modifier.padding(end = 10.dp)
                                                )
                                                Text(
                                                    text = topic.title,
                                                    color = Color(0xFF737373),
                                                    fontSize = 12.sp,
                                                    fontWeight = FontWeight.Medium
                                                )
                                            }
                                            Text(
                                                text = "→",
                                                color = PastelIceBlue,
                                                fontSize = 14.sp
                                            )
                                        }
                                        HorizontalDivider(color = DarkBorder.copy(alpha = 0.5f), thickness = 0.5.dp)
                                    }
                                }
                            }
                        }
                    }
                }
            }
        }
    }

    // Reading Dialog Popup
    if (selectedTopic != null) {
        Dialog(onDismissRequest = { selectedTopic = null }) {
            Card(
                colors = CardDefaults.cardColors(containerColor = DarkCard),
                shape = RoundedCornerShape(16.dp),
                modifier = Modifier
                    .fillMaxWidth()
                    .fillMaxHeight(0.75f)
                    .border(1.5.dp, DarkBorder, RoundedCornerShape(16.dp))
            ) {
                Column(
                    modifier = Modifier
                        .fillMaxSize()
                        .padding(16.dp)
                ) {
                    // Title Bar
                    Row(
                        modifier = Modifier.fillMaxWidth(),
                        horizontalArrangement = Arrangement.SpaceBetween,
                        verticalAlignment = Alignment.CenterVertically
                    ) {
                        Text(
                            text = "📚 Therapeutic Guide",
                            color = SoftPurple,
                            fontSize = 12.sp,
                            fontWeight = FontWeight.Bold
                        )
                        IconButton(
                            onClick = { selectedTopic = null },
                            modifier = Modifier.size(24.dp)
                        ) {
                            Text("❌", color = Color.White, fontSize = 12.sp)
                        }
                    }

                    Spacer(modifier = Modifier.height(12.dp))

                    val isUnderstandingUrticaria = selectedTopic!!.title == "Understanding Urticaria"
